fn statements(a: u64, b: u64) -> u64
  ! pure
  requires true
  ensures result == a
{
  let mut x: u64 = a;
  x = b;
  if true { x = a; } else { x = b; }
  loop
    keeps true
    measures 0
  {
    break;
  }
  x;
